INSERT INTO feature VALUES('store-account','storage','The store account of each stored value','store-facade','implemented','notable',NULL,'Each value that a root of the store names, as a receipt, a stratum or an export, has one row, keyed by its content pointer. So has each identity that a lock records. A row states where the value resides, the bytes and the count of its chunks, and the in-degree of its root chunk. That in-degree is the number of the stored values whose closure holds the chunk. A refused chunk is the refusal of its row. The commit, the world, the location-addressable memory and the reduct are owed cells, and each names its unit. The hub reads the store under its data directory for each renderer that attaches, and it walks each new closure once. The card goes on the render bus.','storage-values storage-store surface-dispatcher surface-render-remote surface-lsp surface-driver','crates/storage-values/tests/closure.rs crates/storage-store/tests/store.rs crates/surface-dispatcher/src/stored.rs crates/surface-render-remote/src/wire.rs crates/surface-lsp/src/hub.rs crates/surface-driver/tests/cli.rs','crate-tests','#6296');
